<?php require '../common.php'; startpage('Librarian Admin');nav('<a href="index.php">Catalog</a><a href="history.php">Borrow history</a><a href="materials.php">Materials</a>');$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){if($_POST['action']==='add'){$s=$conn->prepare('INSERT INTO books(title,author,category) VALUES(?,?,?)');$s->bind_param('sss',$_POST['title'],$_POST['author'],$_POST['category']);$s->execute();$msg='Book added.';}elseif($_POST['action']==='delete'){$id=(int)$_POST['id'];$conn->query("DELETE FROM books WHERE id=$id");$msg='Book deleted.';}}
if($msg)echo '<p class="msg">'.e($msg).'</p>';?>
<form method="post"><h2>Add book</h2><input type="hidden" name="action" value="add"><input name="title" placeholder="Title" required><input name="author" placeholder="Author" required><input name="category" placeholder="Category"><button>Add</button></form>
<table><tr><th>Book</th><th>Author</th><th>Available</th><th>Delete</th></tr><?php $rs=$conn->query('SELECT * FROM books');while($b=$rs->fetch_assoc()):?><tr><td><?=e($b['title'])?></td><td><?=e($b['author'])?></td><td><?=$b['available']?></td><td><form method="post"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$b['id']?>"><button>Delete</button></form></td></tr><?php endwhile;?></table><?php endpage();?>